const number = (value) => Number(value || 0).toLocaleString('pt-BR')
const normalizeText = (value) => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim()
const percent = (value, total) => total ? `${Math.round((value / total) * 100)}%` : '0%'

function App() {
  const [search, setSearch] = useState('')
  const [campus, setCampus] = useState('Todos')
  const [activePage, setActivePage] = useState('overview')
  const [waitingSearch, setWaitingSearch] = useState('')
  const [waitingCourse, setWaitingCourse] = useState('Todos')
  const [waitingCampus, setWaitingCampus] = useState('Todos')
  const [waitingModality, setWaitingModality] = useState('Todos')
  const [waitingStatus, setWaitingStatus] = useState('Todos')
  const [theme, setTheme] = useState(() => localStorage.getItem('acompanha-theme') || 'light')

  useEffect(() => {
    document.documentElement.dataset.theme = theme
    localStorage.setItem('acompanha-theme', theme)
  }, [theme])

  const uniqueWaitingByCourse = waitingList.reduce((courseMap, candidate) => {
    const courseKey = candidate.course
    const candidateKey = candidate.registration || candidate.candidate
    if (!courseMap.has(courseKey)) courseMap.set(courseKey, new Map())
    const candidatesInCourse = courseMap.get(courseKey)
    const wasCalled = candidate.status === 'Convocado' || (candidate.calledModality && candidate.calledModality !== '-')
    const wasFirstCall = candidate.call === '1º Lista de espera' && Boolean(wasCalled)
    const wasSecondCall = candidate.call === '2º Lista de espera' && Boolean(wasCalled)
    const existing = candidatesInCourse.get(candidateKey)
    if (!existing) {
      candidatesInCourse.set(candidateKey, {
        called: Boolean(wasCalled),
        firstCall: Boolean(wasFirstCall),
        secondCall: Boolean(wasSecondCall),
      })
    } else {
      existing.called = existing.called || Boolean(wasCalled)
      existing.firstCall = existing.firstCall || Boolean(wasFirstCall)
      existing.secondCall = existing.secondCall || Boolean(wasSecondCall)
    }
    return courseMap
  }, new Map())

  const coursesWithDistinctWaiting = courses.map((course) => {
    const uniqueCandidates = [...(uniqueWaitingByCourse.get(course.name)?.values() || [])]
    const firstCall = uniqueCandidates.filter((candidate) => candidate.firstCall).length
    const secondCall = uniqueCandidates.filter((candidate) => candidate.secondCall).length
    const called = uniqueCandidates.filter((candidate) => candidate.called).length
    return {
      ...course,
      waitingTotal: uniqueCandidates.length,
      firstCall,
      secondCall,
      awaiting: uniqueCandidates.length - called,
    }
  })

  const filteredCourses = coursesWithDistinctWaiting.filter((course) => {
    const matchesSearch = `${course.name} ${course.campus}`.toLowerCase().includes(search.toLowerCase())
    const matchesCampus = campus === 'Todos' || course.campus === campus
    return matchesSearch && matchesCampus
  })

  const hasOverviewFilter = Boolean(search.trim()) || campus !== 'Todos'

  const totals = filteredCourses.reduce((acc, course) => ({
    vacancies: acc.vacancies + course.vacancies,
    occupied: acc.occupied + course.occupied,
    remaining: acc.remaining + course.remaining,
    firstCall: acc.firstCall + course.firstCall,
    firstCallOccupied: acc.firstCallOccupied + course.firstCallOccupied,
    secondCall: acc.secondCall + course.secondCall,
    secondCallOccupied: acc.secondCallOccupied + course.secondCallOccupied,
    waitingTotal: acc.waitingTotal + course.waitingTotal,
    awaiting: acc.awaiting + course.awaiting,
  }), {
    vacancies: 0, occupied: 0, remaining: 0,
    firstCall: 0, firstCallOccupied: 0,
    secondCall: 0, secondCallOccupied: 0,
    waitingTotal: 0, awaiting: 0,
  })

  const filteredCalls = calls.map((call) => {
    if (!hasOverviewFilter) return call
    if (call.name === 'Chamada Regular') {
      return {
        ...call,
        vacancies: totals.vacancies,
        occupied: totals.occupied,
        remaining: totals.remaining,
        summoned: totals.vacancies,
      }
    }
    if (call.name === '1º Chamada da lista de espera') {
      return {
        ...call,
        vacancies: totals.firstCall,
        occupied: totals.firstCallOccupied,
        remaining: Math.max(0, totals.firstCall - totals.firstCallOccupied),
        summoned: totals.firstCall,
      }
    }
    if (call.name === '2º Chamada da lista de espera') {
      return {
        ...call,
        vacancies: totals.secondCall,
        occupied: totals.secondCallOccupied,
        remaining: Math.max(0, totals.secondCall - totals.secondCallOccupied),
        summoned: totals.secondCall,
      }
    }
    return call
  })

  const modalitySource = hasOverviewFilter ? modalityByCourse : modalityRows
  const filteredModalityRows = [...modalitySource
    .filter((row) => {
      const searchTerm = normalizeText(search)
      if (!hasOverviewFilter) return true
      const matchesSearch = !searchTerm || normalizeText(`${row.course} ${row.campus}`).includes(searchTerm)
      const matchesCampus = campus === 'Todos' || row.campus === campus
      return matchesSearch && matchesCampus
    })
    .reduce((modalityMap, row) => {
      const current = modalityMap.get(row.modality) || { name: row.modality, vacancies: 0, occupied: 0, remaining: 0 }
      current.vacancies += row.vacancies
      current.occupied += row.occupied
      current.remaining += row.remaining
      modalityMap.set(row.modality, current)
      return modalityMap
    }, new Map())
    .values()]

  const filteredWaitingRows = waitingList.filter((candidate) => {
    const term = normalizeText(waitingSearch)
    const normalizedName = normalizeText(candidate.candidate)
    const matchesSearch = !term || normalizedName.includes(term)
    const matchesCourse = waitingCourse === 'Todos' || candidate.course === waitingCourse
    const matchesCampus = waitingCampus === 'Todos' || candidate.campus === waitingCampus
    const matchesModality = waitingModality === 'Todos' || candidate.modality === waitingModality
    const matchesStatus = waitingStatus === 'Todos' || candidate.status === waitingStatus
    return matchesSearch && matchesCourse && matchesCampus && matchesModality && matchesStatus
  })

  const filteredWaiting = Array.from(filteredWaitingRows.reduce((map, candidate) => {
    const key = candidate.registration || candidate.candidate
    const existing = map.get(key)
    if (!existing) {
      map.set(key, { ...candidate, modalities: [candidate.modality], calledModalities: candidate.calledModality !== '-' ? [candidate.calledModality] : [], classifications: [{ modality: candidate.modality, value: candidate.classification }] })
    } else {
      if (!existing.modalities.includes(candidate.modality)) existing.modalities.push(candidate.modality)
      if (candidate.calledModality !== '-' && !existing.calledModalities.includes(candidate.calledModality)) existing.calledModalities.push(candidate.calledModality)
      if (!existing.classifications.some((item) => item.modality === candidate.modality)) existing.classifications.push({ modality: candidate.modality, value: candidate.classification })
      if (candidate.status === 'Convocado') existing.status = 'Convocado'
    }
    return map
  }, new Map()).values()).map((candidate) => ({ ...candidate, modality: candidate.modalities.join(' / '), calledModality: candidate.calledModalities.join(' / ') || '—' })).sort((a, b) => {
    const rankA = Math.min(...a.classifications.map((item) => Number(item.value) || Number.POSITIVE_INFINITY))
    const rankB = Math.min(...b.classifications.map((item) => Number(item.value) || Number.POSITIVE_INFINITY))
    return rankA - rankB || a.candidate.localeCompare(b.candidate, 'pt-BR')
  })

  const waitingStats = filteredWaiting.reduce((acc, candidate) => ({
    total: acc.total + 1,
    waiting: acc.waiting + (candidate.status === 'Aguardando convocação' ? 1 : 0),
    called: acc.called + (candidate.status === 'Convocado' ? 1 : 0),
  }), { total: 0, waiting: 0, called: 0 })
  const visibleWaiting = filteredWaiting.slice(0, 250)

  const regularCall = filteredCalls.find((call) => call.name === 'Chamada Regular') || filteredCalls[0] || { vacancies: 0, occupied: 0, remaining: 0 }
  const processCapacity = regularCall.vacancies || 1
  let cumulativeOccupied = 0
  const occupationSnapshots = filteredCalls.map((call) => {
    const newlyOccupied = call.name === 'Chamada Regular' ? call.occupied : Math.max(0, call.occupied)
    cumulativeOccupied = Math.min(processCapacity, cumulativeOccupied + newlyOccupied)
    const remaining = Math.max(0, processCapacity - cumulativeOccupied)
    return {
      ...call,
      occupied: cumulativeOccupied,
      remaining,
      rate: processCapacity ? (cumulativeOccupied / processCapacity) * 100 : 0,
    }
  })
  const currentSnapshot = occupationSnapshots[occupationSnapshots.length - 1] || { occupied: 0, remaining: processCapacity, rate: 0 }
  const currentOccupied = currentSnapshot.occupied
  const currentRemaining = currentSnapshot.remaining
  const currentRate = currentSnapshot.rate
  const formatRate = (value) => `${value.toFixed(1).replace('.', ',')}%`
  // Cada ponto fica no centro do grupo de barras correspondente à sua chamada.
  // A escala de vagas usa uma margem superior discreta para preservar os rótulos.
  const chartMax = Math.max(1, Math.ceil((processCapacity * 1.15) / 10) * 10)
  // Transformação direta do eixo direito: 100% no topo e 0% na base do plot.
  // A linha percentual usa uma faixa superior própria; assim, sua escala nunca invade barras ou rótulos.
  const lineBandTop = 4
  const lineBandHeight = 50
  // Compress the percentage scale into the upper band of the chart.
  // 100% stays near the top; 0% still remains above the bar stack.
  const occupancyLineY = (rate) => 10 + ((100 - Math.max(0, Math.min(100, rate))) * 0.35)
  const pointX = (index) => ((index + 0.5) / Math.max(occupationSnapshots.length, 1)) * 100
  const occupancyPoints = occupationSnapshots.map((call, index) => `${pointX(index)},${occupancyLineY(call.rate)}`).join(' ')
  const vacancyTicks = [1, .75, .5, .25, 0].map((ratio) => Math.round(chartMax * ratio))
  const rateTicks = [100, 75, 50, 25, 0]

  return (
    <div className={`app-shell ${theme === 'dark' ? 'theme-dark' : 'theme-light'}`}>
      <aside className="sidebar">
        <div className="brand institutional-sidebar-brand"><img className="sidebar-linear-logo" src="/logo-ufpi.png" alt="Logo linear da Universidade Federal do Piauí" /><div className="sidebar-institution-copy"><strong>UFPI · PREG</strong></div></div>
        <nav className="navigation">
          <button className={`navigation-item ${activePage === 'overview' ? 'active' : ''}`} onClick={() => setActivePage('overview')}><UiIcon name="dashboard" size={16} /> <span>Visão geral</span></button>
          <button className={`navigation-item ${activePage === 'waiting' ? 'active' : ''}`} onClick={() => setActivePage('waiting')}><UiIcon name="list" size={16} /> <span>Lista de espera</span></button>
        </nav>
        <div className="privacy-note"><strong>Transparência dos dados</strong><span>Indicadores oficiais apresentados sem estimativas ou projeções.</span></div>
      </aside>

      <main className="main-content">
                {activePage === 'waiting' ? (
          <section className="waiting-page">
            <section className="page-heading compact-heading"><div><span className="eyebrow">CONSULTA INDIVIDUAL</span><h1>Lista de Espera</h1><p>Consulte a classificação publicada oficialmente pela UFPI, organizada por curso, campus e modalidade.</p></div><div className="source-card"><span>Fonte oficial</span><strong>Base publicada pela UFPI</strong></div></section>
            <section className="waiting-kpis" aria-label="Indicadores da lista de espera"><article className="kpi-card"><span className="kpi-label"><i className="data-icon candidates-icon" aria-hidden="true">◎</i> Registros no recorte</span><strong>{number(waitingStats.total)}</strong><small>Resultado dos filtros aplicados</small></article><article className="kpi-card"><span className="kpi-label"><i className="data-icon waiting-icon" aria-hidden="true">◷</i> Aguardando convocação</span><strong>{number(waitingStats.waiting)}</strong><small>Classificados sem chamada registrada</small></article><article className="kpi-card highlight"><span className="kpi-label"><i className="data-icon called-icon" aria-hidden="true">✓</i> Convocados</span><strong>{number(waitingStats.called)}</strong><small>Chamada registrada na base oficial</small></article></section>
            <section className="panel waiting-panel"><div className="panel-heading"><div><span className="eyebrow">BUSCA E FILTROS</span><h2>Localize seu registro</h2><p className="panel-caption">Os nomes são exibidos conforme a publicação oficial. CPFs não são reproduzidos nesta interface.</p></div></div><div className="waiting-filters"><label className="filter-control search-filter"><span>Nome do candidato</span><input value={waitingSearch} onChange={(event) => setWaitingSearch(event.target.value)} placeholder="Digite o nome" aria-label="Buscar por nome do candidato" /></label><label className="filter-control"><span>Curso</span><select value={waitingCourse} onChange={(event) => setWaitingCourse(event.target.value)}><option>Todos</option>{[...new Set(waitingList.map((item) => item.course))].map((item) => <option key={item}>{item}</option>)}</select></label><label className="filter-control"><span>Campus</span><select value={waitingCampus} onChange={(event) => setWaitingCampus(event.target.value)}><option>Todos</option>{[...new Set(waitingList.map((item) => item.campus))].map((item) => <option key={item}>{item}</option>)}</select></label><label className="filter-control"><span>Modalidade</span><select value={waitingModality} onChange={(event) => setWaitingModality(event.target.value)}><option>Todos</option>{[...new Set(waitingList.map((item) => item.modality))].map((item) => <option key={item}>{item}</option>)}</select></label><label className="filter-control"><span>Situação</span><select value={waitingStatus} onChange={(event) => setWaitingStatus(event.target.value)}><option>Todos</option><option>Aguardando convocação</option><option>Convocado</option></select></label>{(waitingSearch || waitingCourse !== 'Todos' || waitingCampus !== 'Todos' || waitingModality !== 'Todos' || waitingStatus !== 'Todos') && <button className="clear-button" type="button" onClick={() => { setWaitingSearch(''); setWaitingCourse('Todos'); setWaitingCampus('Todos'); setWaitingModality('Todos'); setWaitingStatus('Todos') }} aria-label="Limpar filtros da lista de espera">Limpar filtros</button>}</div></section>
            <section className="panel waiting-panel"><div className="panel-heading"><div><span className="eyebrow">LISTA PUBLICADA</span><h2>Classificação dos candidatos</h2></div><span className="panel-caption">{number(filteredWaiting.length)} registros exibidos</span></div><div className="table-container waiting-table-container">{filteredWaiting.length === 0 ? <div className="empty-state" role="status">Nenhum candidato encontrado com os filtros atuais.</div> : <table key={`${waitingSearch}|${waitingCourse}|${waitingCampus}|${waitingModality}|${waitingStatus}`} className="waiting-table"><thead><tr><th>Nome</th><th>Curso</th><th>Campus</th><th>Convocação</th><th>Classificação</th><th>Nota</th><th>Situação</th></tr></thead><tbody>{visibleWaiting.map((candidate) => <tr key={`${candidate.registration}-${candidate.course}`}><td><strong>{candidate.candidate}</strong><small>Inscrição: {candidate.registration}</small></td><td>{candidate.courseShort}</td><td>{candidate.campus}</td><td><strong className="called-modality">{candidate.calledModality}</strong></td><td>{candidate.classifications.map((item) => `${item.modality}: ${number(item.value)}º`).join(' · ')}</td><td>{candidate.score == null ? '—' : candidate.score.toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 })}</td><td><span className={`waiting-status ${candidate.status === 'Convocado' ? 'called' : 'pending'}`}>{candidate.status}</span></td></tr>)}</tbody></table>} </div>{filteredWaiting.length > 250 && <div className="waiting-limit"></div>}<div className="modality-footer"><span>.</span></div></section>
          </section>
        ) : (
          <>
        <section className="page-heading"><div className="institutional-lockup"><img src="/logo-ufpi.png" alt="Brasão da Universidade Federal do Piauí" /><div><span className="institution-name">UNIVERSIDADE FEDERAL DO PIAUÍ</span><span className="institution-unit">PRÓ-REITORIA DE ENSINO DE GRADUAÇÃO</span><h1>Acompanhamento da lista de espera do SISU</h1><p>Monitoramento institucional de vagas, ocupações e convocações.</p></div></div><div className="institutional-actions"><button className="theme-toggle" type="button" onClick={() => setTheme((current) => current === 'light' ? 'dark' : 'light')} aria-label={theme === 'light' ? 'Ativar tema escuro' : 'Ativar tema claro'} title={theme === 'light' ? 'Tema escuro' : 'Tema claro'}><span aria-hidden="true">{theme === 'light' ? '☾' : '☀'}</span><strong>{theme === 'light' ? 'Escuro' : 'Claro'}</strong></button></div></section>

        <section className="filters" aria-label="Filtros do dashboard">
          <select value={campus} onChange={(event) => setCampus(event.target.value)}><option>Todos</option><option>CAFS</option><option>CCN</option><option>CCE</option></select>
          <input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar curso ou campus" aria-label="Buscar curso ou campus" />
          {(search || campus !== 'Todos') && <button className="clear-button" onClick={() => { setSearch(''); setCampus('Todos') }} aria-label="Limpar filtros do painel">Limpar filtros</button>}
          {hasOverviewFilter && <div className="active-filter-summary" aria-live="polite"><span>Recorte ativo</span>{campus !== 'Todos' && <b>Campus: {campus}</b>}{search && <b>Busca: {search}</b>}</div>}
        </section>

        <section className="kpi-grid" aria-label="Indicadores principais">
          <article className="kpi-card overview-kpi">
            <div className="kpi-icon kpi-icon-blue"><UiIcon name="vacancies" /></div>
            <div><span className="kpi-label">Vagas ofertadas</span><strong>{number(totals.vacancies)}</strong><small>Chamada regular</small></div>
          </article>
          <article className="kpi-card overview-kpi">
            <div className="kpi-icon kpi-icon-green"><UiIcon name="occupied" /></div>
            <div><span className="kpi-label">Vagas ocupadas</span><strong>{number(currentOccupied)}</strong><small>{percent(currentOccupied, totals.vacancies)} da oferta</small></div>
          </article>
          <article className="kpi-card overview-kpi">
            <div className="kpi-icon kpi-icon-amber"><UiIcon name="remaining" /></div>
            <div><span className="kpi-label">Vagas remanescentes</span><strong>{number(currentRemaining)}</strong><small>{percent(currentRemaining, totals.vacancies)} da oferta</small></div>
          </article>
          <article className="kpi-card overview-kpi">
            <div className="kpi-icon kpi-icon-slate"><UiIcon name="waiting" /></div>
            <div><span className="kpi-label">Lista de espera</span><strong>{number(totals.waitingTotal)}</strong><small>{number(totals.firstCall)} convocados na 1ª · {number(totals.secondCall)} convocados na 2ª chamada</small></div>
          </article>
        </section>

        <section className="insight-card overview-insight">
          <div className="insight-icon"><UiIcon name="dashboard" size={17} /></div>
          <div><strong>Visão geral do processo</strong><p>{percent(currentOccupied, totals.vacancies)} das vagas estão ocupadas. Restam {number(currentRemaining)} vagas para as próximas chamadas.</p></div>
        </section>

        <section className="overview-grid">
          <article className="panel demand-panel">
            <div className="panel-heading">
              <div><span className="eyebrow">DISPONIBILIDADE POR CURSO</span><h2>Onde ainda existem vagas?</h2></div>
              <span className="panel-caption">Situação atual</span>
            </div>
            <div className="bars">
              {filteredCourses.length === 0 ? <div className="empty-state" role="status">Nenhum curso encontrado com os filtros atuais.</div> : filteredCourses.map((course) => {
                const courseCurrentOccupied = course.occupied + course.firstCallOccupied + course.secondCallOccupied
                const courseCurrentRemaining = Math.max(0, course.vacancies - courseCurrentOccupied)
                const occupiedRate = course.vacancies ? (courseCurrentOccupied / course.vacancies) * 100 : 0
                const remainingRate = course.vacancies ? (courseCurrentRemaining / course.vacancies) * 100 : 0
                return <div className="bar-row" key={course.name}>
                  <div><span>{course.name}</span><b>{number(courseCurrentRemaining)} vagas disponíveis</b></div>
                  <div className="bar-track"><i style={{ width: `${Math.min(occupiedRate, 100)}%` }} /></div>
                  <div className="bar-meta"><span>{number(courseCurrentOccupied)} ocupadas</span><strong>{remainingRate.toFixed(1).replace('.', ',')}% livres</strong></div>
                </div>
              })}
            </div>
            <div className="demand-legend"><span><i className="demand-occupied-key" /> Ocupadas</span><span><i className="demand-empty-key" /> Disponíveis</span></div>
          </article>

          <section className="panel modality-panel overview-modality-panel">
            <div className="panel-heading">
              <div><span className="eyebrow">DISTRIBUIÇÃO DAS VAGAS</span><h2>Ocupação por modalidade</h2></div>
              {hasOverviewFilter && <span className="modality-source"><i className="source-icon" aria-hidden="true">✓</i> Recorte por curso/campus</span>}
            </div>
            <div className="table-container modality-table-container">
              <table className="modality-table">
                <thead><tr><th>Modalidade</th><th>Vagas<br />ofertadas</th><th>Vagas<br />ocupadas</th><th>Vagas<br />remanescentes</th><th>Progresso<br />da ocupação</th></tr></thead>
                <tbody>{(hasOverviewFilter ? filteredModalityRows : modalityRows).map((row) => {
                  const rate = row.vacancies ? (row.occupied / row.vacancies) * 100 : 0
                  return <tr key={row.name}>
                    <td><strong>{row.name}</strong></td>
                    <td>{number(row.vacancies)}</td>
                    <td>{number(row.occupied)}</td>
                    <td>{number(row.remaining)}</td>
                    <td><div className="modality-progress">
                      <div className="modality-progress-label">
                        <span>{rate.toFixed(1).replace('.', ',')}%</span>
                        <small>{number(row.occupied)} de {number(row.vacancies)}</small>
                      </div>
                      <div className="modality-track"><i style={{ width: `${Math.min(rate, 100)}%` }} /></div>
                    </div></td>
                  </tr>
                })}</tbody>
              </table>
            </div>
          </section>
        </section>

        <section className="overview-analysis-grid">
          <section className="panel cumulative-panel process-chart-panel overview-process-panel">
          <div className="panel-heading process-heading">
            <div>
              <span className="eyebrow">EVOLUÇÃO DO PROCESSO</span>
              <h2>Ocupação acumulada por chamada</h2>
              {hasOverviewFilter && <p className="panel-caption">Evolução recalculada para o recorte selecionado.</p>}
            </div>
          </div>

          <div className="cumulative-chart" role="img" aria-label="Evolução acumulada das vagas ocupadas e remanescentes por chamada">

            <div className="cumulative-plot">
              <div className="cumulative-grid" aria-hidden="true">
                <i /><i /><i /><i /><i />
              </div>

              <div className="cumulative-line-layer" aria-hidden="true">
                <svg className="cumulative-line-svg" viewBox="0 0 100 100" preserveAspectRatio="none">
                  <polyline
                    className="cumulative-line-path"
                    points={occupancyPoints}
                    fill="none"
                    vectorEffect="non-scaling-stroke"
                  />
                  {occupationSnapshots.map((call, index) => {
                    const x = pointX(index)
                    const y = occupancyLineY(call.rate)
                    return <circle key={`cum-svg-point-${index}`} className="cumulative-svg-point" cx={x} cy={y} r="0.75" vectorEffect="non-scaling-stroke" />
                  })}
                </svg>
                {occupationSnapshots.map((call, index) => {
                  const x = pointX(index)
                  const y = occupancyLineY(call.rate)
                  return <span key={`cum-point-${index}`} className="cumulative-line-point-label" style={{ left: `${x}%`, top: `${y}%` }}>
                    <b>{formatRate(call.rate)}</b>
                  </span>
                })}
              </div>

              <div className="cumulative-columns">
                {occupationSnapshots.map((call) => {
                  const occupiedPct = processCapacity ? (call.occupied / processCapacity) * 100 : 0
                  const remainingPct = processCapacity ? (call.remaining / processCapacity) * 100 : 0
                  return (
                    <div className="cumulative-column" key={call.name}>
                      <div className="cumulative-stack">
                        <div className="cumulative-remaining" style={{ height: `${remainingPct}%` }}>
                          <span className="cumulative-remaining-label">{number(call.remaining)}</span>
                        </div>
                        <div className="cumulative-occupied" style={{ height: `${occupiedPct}%` }}>
                          <span className="cumulative-bar-label">{number(call.occupied)}</span>
                        </div>
                      </div>
                      <span className="cumulative-call-label">
                        {call.name === 'Chamada Regular' ? <>Chamada<br />Regular</> : call.name}
                      </span>
                    </div>
                  )
                })}
              </div>
            </div>
          </div>

          <div className="chart-legend process-legend-v2" aria-label="Legenda do gráfico de ocupação acumulada">
            <span><i className="occupied-dot" /> Ocupadas acumuladas</span>
            <span><i className="remaining-dot" /> Vagas remanescentes</span>
            <span><i className="rate-dot" /> Taxa de ocupação acumulada</span>
          </div>
        

          
        </section>

          <section className="panel table-panel"><div className="panel-heading"><div><span className="eyebrow">VAGAS POR CURSO</span><h2>Distribuição das vagas e convocações</h2></div></div><div className="table-container"><table><thead><tr><th>Curso</th><th>Campus</th><th>Vagas</th><th>Ocupadas</th><th>Remanescentes</th><th>Convocados<br />1ª chamada</th><th>Convocados<br />2ª chamada</th><th>Aguardando</th></tr></thead><tbody>{filteredCourses.map((course) => { const courseCurrentOccupied = course.occupied + course.firstCallOccupied + course.secondCallOccupied; const courseCurrentRemaining = Math.max(0, course.vacancies - courseCurrentOccupied); return <tr key={course.name}><td><strong>{course.name}</strong></td><td>{course.campus}</td><td>{number(course.vacancies)}</td><td>{number(courseCurrentOccupied)}</td><td>{number(courseCurrentRemaining)}</td><td>{number(course.firstCall)}</td><td>{number(course.secondCall)}</td><td>{number(course.awaiting)}</td></tr> })}</tbody></table></div></section>

          
        </section>

        

        <footer>ACOMPANHA UFPI · SISU 2026</footer>
        </>)}
      </main>
    </div>
  )
}

export default App
